import { Check, Copy, LoaderCircle, Search, TerminalSquare } from "lucide-react";
import { useDeferredValue, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { useSearchParams } from "react-router-dom";
import { PageHeader } from "../components/PageHeader";
import { SeoHead } from "../components/SeoHead";
import { commandGroups, localizedText, totalCommands } from "../data/project";
import { usePreferences } from "../hooks/usePreferences";
import { copyText } from "../lib/clipboard";
import { fuzzySearchScore } from "../lib/search";

function CommandCopy({ value }: { value: string }) {
  const { t } = useTranslation();
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    const success = await copyText(value);
    setCopied(success);
    window.setTimeout(() => setCopied(false), 1400);
  };
  return <button className={`icon-button command-copy ${copied ? "success" : ""}`} type="button" onClick={copy} aria-label={`${t("common.copy")} ${value}`} title={t("common.copyCommand")}>{copied ? <Check size={15} /> : <Copy size={15} />}<span className="copy-tooltip" aria-live="polite">{copied ? t("common.copied") : ""}</span></button>;
}

export function CommandsPage() {
  const { t } = useTranslation();
  const { language } = usePreferences();
  const [params, setParams] = useSearchParams();
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);
  const requestedGroup = params.get("group");
  const activeGroup = commandGroups.find((group) => group.id === requestedGroup) ?? commandGroups[0];
  const commands = useMemo(() => {
    const needle = deferredQuery.trim();
    if (!needle) return activeGroup.commands;
    return activeGroup.commands
      .map((command) => ({ command, score: fuzzySearchScore(`${command.name} ${command.usage} ${command.examples.join(" ")} ${command.tags.join(" ")} ${command.summary} ${command.summaryEn ?? ""}`, needle) }))
      .filter((item) => Number.isFinite(item.score))
      .sort((left, right) => left.score - right.score)
      .map((item) => item.command);
  }, [activeGroup, deferredQuery]);

  return (
    <>
      <SeoHead titleKey="seo.commandsTitle" descriptionKey="seo.commandsDescription" path="docs/commands" />
      <div className="page page--commands">
        <PageHeader index="01" eyebrow={t("commandsPage.eyebrow").toUpperCase()} title={t("commandsPage.title")} description={t("commandsPage.description", { count: totalCommands })} aside={<div className="header-stat"><strong>{totalCommands}</strong><span>{t("commandsPage.entries").toUpperCase()}</span></div>} />

        <section className="command-explorer reveal-in reveal-delay-1">
          <aside className="command-groups" aria-label={t("commandsPage.groups")}>
            {commandGroups.map((group, index) => (
              <button type="button" className={group.id === activeGroup.id ? "active" : ""} onClick={() => { setParams({ group: group.id }); setQuery(""); }} key={group.id}>
                <span>0{index + 1}</span><div><b>{localizedText(group.label, group.labelEn, language)}</b><small>{group.commands.length} {t("common.commands")}</small></div>
              </button>
            ))}
          </aside>
          <div className="command-directory">
            <div className="command-directory__head">
              <div><span>/{activeGroup.id}</span><h2>{localizedText(activeGroup.label, activeGroup.labelEn, language)}</h2><p>{localizedText(activeGroup.description, activeGroup.descriptionEn, language)}</p></div>
              <div className="filter-stack">
                <label className="filter-input"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("commandsPage.filter")} aria-label={t("commandsPage.filter")} />{query !== deferredQuery ? <LoaderCircle className="spin" size={14} /> : null}</label>
                <span className="filter-status" aria-live="polite">{query !== deferredQuery ? t("commandsPage.filtering") : t("commandsPage.matched", { count: commands.length })}</span>
              </div>
            </div>
            <div className="command-list">
              {commands.map((command) => (
                <article className="command-entry" key={command.name}>
                  <div className="command-entry__title"><TerminalSquare size={17} /><h3>{command.name}</h3><CommandCopy value={command.examples[0]} /></div>
                  <p>{localizedText(command.summary, command.summaryEn, language)}</p>
                  <div className="usage-line"><span>{t("commandsPage.usage").toUpperCase()}</span><code>{command.usage}</code></div>
                  <div className="example-stack">{command.examples.map((example) => <code key={example}><i>$</i>{example}</code>)}</div>
                  <footer><div>{command.tags.map((tag) => <span key={tag}>{tag}</span>)}</div><small>{command.evidence}</small></footer>
                </article>
              ))}
              {commands.length === 0 ? <div className="empty-state"><Search size={22} /><span>{t("commandsPage.empty")}</span></div> : null}
            </div>
          </div>
        </section>
      </div>
    </>
  );
}
